'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isEqual = require( '@stdlib/number/uint64/base/assert/is-equal' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Uint64Array = require( './../lib' );


// MAIN //

bench( format( '%s:findLast', pkg ), function benchmark( b ) {
	var arr;
	var out;
	var v;
	var i;

	arr = new Uint64Array( 10 );

	v = new Uint64( 1 );

	// Benchmark worst case scenario (i.e., the predicate never passes, so the method must visit every element)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.findLast( predicate );
		if ( typeof out !== 'undefined' ) {
			b.fail( 'should return undefined' );
		}
	}
	b.toc();
	if ( typeof out !== 'undefined' ) {
		b.fail( 'should return undefined' );
	}
	b.pass( 'benchmark finished' );
	b.end();

	function predicate( u ) {
		return isEqual( u, v );
	}
});

bench( format( '%s::this_context:findLast', pkg ), function benchmark( b ) {
	var arr;
	var out;
	var v;
	var i;

	arr = new Uint64Array( 10 );

	v = new Uint64( 1 );

	// Benchmark worst case scenario (i.e., the predicate never passes, so the method must visit every element)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.findLast( predicate, {} );
		if ( typeof out !== 'undefined' ) {
			b.fail( 'should return undefined' );
		}
	}
	b.toc();
	if ( typeof out !== 'undefined' ) {
		b.fail( 'should return undefined' );
	}
	b.pass( 'benchmark finished' );
	b.end();

	function predicate( u ) {
		return isEqual( u, v );
	}
});
